// ASK 227 rev 2: the HTTP node emits one item PER ROW (execution 36577), so rows come from every input item.
// The two older shapes (the whole array as one item, or an object with one key holding it) are still accepted.
const ins = $input.all().map(i => i.json);
let rows = [];
if (ins.length === 1 && Array.isArray(ins[0])) {
  rows = ins[0];
} else if (ins.length === 1 && ins[0] && typeof ins[0] === 'object' && !('table_name' in ins[0]) && Object.keys(ins[0]).length === 1) {
  rows = ins[0][Object.keys(ins[0])[0]] || [];
} else {
  rows = ins.filter(r => r && typeof r === 'object' && typeof r.table_name === 'string');
}
if (!rows || rows.length === 0) return [];
const grouped = {};
rows.forEach(r => {
  if (!grouped[r.table_name]) grouped[r.table_name] = [];
  grouped[r.table_name].push(r);
});
return Object.entries(grouped).map(([tableName, tableRows]) => ({
  json: {
    table_name: tableName,
    row_count: tableRows.length,
    rows: tableRows,
    snapshot_ts: new Date().toISOString()
  }
}));

// ASK 227: one file per table group. The RPC marks every fetched row exported, so every group must be written.
return $input.all().map(item => {
const d = item.json;
const ts = d.snapshot_ts;
const tableName = d.table_name;
let content = '# TRUTH App — Table Snapshot\n';
content += '## Table: ' + tableName + '\n';
content += '## Snapshot Time: ' + ts + '\n';
content += '## Change Count: ' + d.row_count + '\n';
content += '## Protected Table: YES — training knowledge target\n\n---\n\n';
d.rows.forEach((r, i) => {
  content += '### Change ' + (i+1) + ' — ' + r.operation + ' at ' + r.triggered_at + '\n';
  content += '```json\n' + JSON.stringify(r.changed_row, null, 2) + '\n```\n\n';
});
const filename = 'Snapshot_' + tableName + '_' + ts.replace(/[:.]/g, '-').replace('T', '_').substring(0, 19) + '.md';
// ASK 228: carry the queue ids so a file Drive refuses can be set back to pending.
return { json: { content, filename, table_name: tableName, snapshot_ts: ts, export_ids: d.rows.map(r => r.id) } };
});

// ASK 228: Drive refused these files on the first try (403 rateLimitExceeded in execution 36648). After the wait, send only those again.
// n8n merges each error item with the input item it came from, so the filename is expected here. If any error item has no filename,
// every file of this run is sent again: a duplicate file is acceptable, a lost batch is not.
const built = $('Build Snapshot Content').all().map(x => x.json);
const errs = $input.all().map(x => x.json || {});
const named = errs.length > 0 && errs.every(e => typeof e.filename === 'string');
let pick = named ? built.filter(b => errs.some(e => e.filename === b.filename)) : built;
if (pick.length === 0) pick = built;
const e0 = errs[0] && errs[0].error;
const first_error = String((e0 && (e0.message || e0.description)) || e0 || 'unknown').slice(0, 300);
return pick.map(b => ({ json: { ...b, first_error } }));

// ASK 228: Drive refused these files twice, 62 s apart. Their rows are already marked exported by get_pending_snapshots,
// so they are set back to pending for the next run. If an error item has no filename, every file sent on the retry is re-queued.
const sent = $('Pick Unsaved Files').all().map(x => x.json);
const errs = $input.all().map(x => x.json || {});
const named = errs.length > 0 && errs.every(e => typeof e.filename === 'string');
let lost = named ? sent.filter(b => errs.some(e => e.filename === b.filename)) : sent;
if (lost.length === 0) lost = sent;
const ids = [...new Set(lost.flatMap(b => Array.isArray(b.export_ids) ? b.export_ids : []))].filter(v => Number.isInteger(v) && v > 0);
if (ids.length === 0) throw new Error('PROTECTED SNAPSHOT: Drive refused ' + lost.length + ' file(s) twice and no queue ids were found to re-queue. Rows stay marked exported: ' + lost.map(b => b.filename).join(', '));
const e0 = errs[0] && errs[0].error;
const error = String((e0 && (e0.message || e0.description)) || e0 || 'unknown').slice(0, 300);
return [{ json: { ids, files: lost.map(b => b.filename), tables: lost.map(b => b.table_name), error } }];

